/* Diagnostic markers: deliberately not substitute character models. */
static void marker34(int x,int y,int z,int size,int color,int cx,int cy,int cz,int sn,int cs){Point v[4];int dx=size*cs>>12,dz=-(size*sn>>12);v[0]=transform(x,y-size,z,cx,cy,cz,sn,cs);v[1]=transform(x+dx,y,z+dz,cx,cy,cz,sn,cs);v[2]=transform(x,y+size,z,cx,cy,cz,sn,cs);v[3]=transform(x-dx,y,z-dz,cx,cy,cz,sn,cs);for(int i=0;i<4;i++)v[i].u=v[i].v=0;worldtri(v[0],v[1],v[2],0x8000|color);worldtri(v[0],v[2],v[3],0x8000|color);}
static void renderquest34(Player18*p,int cx,int cy,int cz,int sn,int cs){for(int j=0;j<cache.count;j++){int k=cache.active[j];const U32*m=cache.meta[k];const U8*t=cache.bytes[k]+64+m[1]*36+m[2]*24;for(U32 n=0;n<m[3];n++,t+=16){if(s18(t+6)!=4)continue;U32 id=rd18(t+12);int x=s18(t)+(int)m[4],y=s18(t+2)+(int)m[5],z=s18(t+4)+(int)m[6];if(ab(x-p->x)>1400||ab(z-p->z)>1400)continue;for(int i=0;i<3;i++){if(id==qnpc34[i])marker34(x,y-130,z,34,quest34.stage[i]==3?0x03e0:0x7fe0,cx,cy,cz,sn,cs);if(id==qtrigger34[i]&&!quest34.stage[i])marker34(x,y-50,z,23,0x03ff,cx,cy,cz,sn,cs);}}}
 for(int i=0;i<3;i++)if(quest34.stage[i]<Q34_RETURNED){int v[3];quest_pos34(&quest34,i,v);if(ab(v[0]-p->x)<=1400&&ab(v[2]-p->z)<=1400)marker34(v[0],v[1]-45,v[2],30,0x7c1f,cx,cy,cz,sn,cs);}}
static void hudquest34(void){static const u32 colors[]={0x707070,0x35b0ff,0xf0c050,0x50df60};static const unsigned short glyph[]={0x7492,0x5bed,0x6b6e};rect(5,204,82,29,0x252027);for(int i=0;i<3;i++){int x=10+i*25;for(int j=0;j<15;j++)if(glyph[i]&(1<<(14-j)))rect(x+j%3*2,208+j/3*2,2,2,0xffffff);rect(x+9,208,12,10,colors[quest34.stage[i]]);if(quest34.near==i)rect(x,220,21,3,0xffffff);}if(quest34.reward)rect(10,226,70,3,0x50df60);}
